"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    """
    Determines if an event topic matches a subscription pattern, respecting
    the hierarchical double-colon (::) segment boundaries.

    A subscription pattern matches an event topic if:
    1. The event topic is an exact match for the subscribed pattern.
    2. The event topic starts with the subscribed pattern followed by '::',
       indicating it's a sub-topic within the subscribed hierarchy.

    This prevents unintended matches like 'orders' matching 'orders_admin'.
    """
    if event_topic == subscribed_pattern:
        return True
    if event_topic.startswith(subscribed_pattern + "::"):
        return True
    return False

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
